class ArticleParts(HTMLParser):
    """Keep exact HTML of direct article children, including the rich case tables."""
    VOID = {'br', 'img', 'input', 'meta', 'link', 'hr', 'source', 'wbr', 'area', 'base', 'col', 'embed', 'param', 'track'}

    def __init__(self, source):
        super().__init__(convert_charrefs=False)
        self.source = source
        self.offsets = [0]
        for line in source.splitlines(keepends=True):
            self.offsets.append(self.offsets[-1] + len(line))
        self.depth = 0
        self.start = 0
        self.kind = ''
        self.parts = []
        self.feed(source)

    def position(self):
        line, column = self.getpos()
        return self.offsets[line - 1] + column

    def handle_starttag(self, tag, attrs):
        if self.depth == 1:
            self.start = self.position()
            self.kind = dict(attrs).get('class', tag)
        if tag not in self.VOID:
            self.depth += 1

    def handle_endtag(self, tag):
        if tag in self.VOID:
            return
        self.depth -= 1
        if self.depth == 1:
            end = self.source.find('>', self.position()) + 1
            self.parts.append((self.kind, self.source[self.start:end]))

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        if tag not in self.VOID:
            self.handle_endtag(tag)


def interactive_scheme(item):
    pid = item['id']
    buttons, inspectors = [], []
    for i, (title, purpose, incoming, outgoing, reason) in enumerate(SCHEMES[pid]):
        selected = i == 0
        buttons.append(f'<button type="button" class="scheme-node" id="{pid}-node-{i}" data-node="{i}" aria-pressed="{str(selected).lower()}" aria-controls="{pid}-inspector"><span>УЗЕЛ {i+1:02}</span><strong>{escape(title)}</strong><small>Смотреть детали ↗</small></button>')
        inspectors.append(f'<section class="node-note" data-node-note="{i}" aria-labelledby="{pid}-node-{i}"><span class="drawing-label">ВЫНОСКА {i+1:02} / 06</span><h4>{escape(title)}</h4><p>{escape(purpose)}</p><dl><div><dt>Вход</dt><dd>{escape(incoming)}</dd></div><div><dt>Выход</dt><dd>{escape(outgoing)}</dd></div></dl><div class="node-reason"><span>Почему этот шаг</span><p>{escape(reason)}</p></div></section>')
    return f'''<div class="sheet-heading"><div><p class="eyebrow">ЛИСТ 02 / АРХИТЕКТУРА</p><h3>Из чего собрано решение.</h3></div><p>Нажмите на узел — откроется выноска<br />с входом, выходом и обоснованием.</p></div>
      <div class="interactive-scheme"><div class="scheme-blueprint"><div class="drawing-register"><span>СХЕМА / {escape(FOLDER_TITLES[pid])}</span><span>06 УЗЛОВ</span></div><div class="scheme-nodes" role="group" aria-label="Узлы архитектуры">{''.join(buttons)}</div><div class="drawing-register drawing-bottom"><span>ВХОД → ОБРАБОТКА → РЕЗУЛЬТАТ</span><span>МАСШТАБ / ЛОГИКА</span></div></div><aside class="node-inspector" id="{pid}-inspector" aria-label="Описание выбранного узла" aria-live="polite">{''.join(inspectors)}</aside></div>'''


