def error_sheet(item):
    pid = item['id']
    rows = []
    for i, (kind, title, observation, handling, status) in enumerate(ERRORS[pid]):
        rows.append(f'''<article class="error-entry"><div class="error-entry-title"><span>{i+1:02} / {escape(kind)}</span><h4>{escape(title)}</h4></div><div class="error-observation"><span>Что важно проверить</span><p>{escape(observation)}</p></div><div class="error-handling"><span>Решение / следующий шаг</span><p>{escape(handling)}</p></div><p class="error-status"><span aria-hidden="true">↳</span>{escape(status)}</p></article>''')
    return f'''<div class="sheet-heading"><div><p class="eyebrow">ЛИСТ 04 / РАЗБОР ОШИБОК</p><h3>Где решение требует внимания.</h3></div><span class="review-stamp" aria-hidden="true">РАЗБОР<br />И ОГРАНИЧЕНИЯ</span></div><p class="sheet-caption">По материалам проекта: наблюдения, обработанные случаи и границы оценки. Статус каждого пункта указан отдельно.</p><div class="error-ledger">{''.join(rows)}</div>'''


def folder_body(item, art, notes, original=None):
    pid = item['id']
    incoming, outgoing, contribution, observation, stack, sample = notes
    if original:
        parts = ArticleParts(original).parts
        task = ''.join(html for kind, html in parts if kind.startswith(('brief-grid', 'contribution')))
        experiment = ''.join(html for kind, html in parts if kind.startswith(('experiments', 'table-block', 'web-experiment', 'case-conclusion')))
        if pid == 'vlm-agent':
            links = '<a href="https://github.com/ZaplatinArtur/VLM_agent_turkish_textbook_ML_academy_Yandex" target="_blank" rel="noreferrer">Код ↗</a><a href="https://zaplatinartur.github.io/VLM_agent_turkish_textbook_ML_academy_Yandex/" target="_blank" rel="noreferrer">Исследование ↗</a>'
        else:
            links = '<a href="https://github.com/ZaplatinArtur/Ural_history_with_RAG" target="_blank" rel="noreferrer">GitHub проекта ↗</a>'
    else:
        links = ''
        task = f'''<div class="sheet-heading"><div><p class="eyebrow">ЛИСТ 01 / ПОСТАНОВКА ЗАДАЧИ</p><h3>{escape(item.get('display_title', item['short']))}</h3></div></div><p class="task-intro">{escape(item['lead'])}</p><dl class="task-io"><div><dt>Вход</dt><dd>{escape(incoming)}</dd></div><div><dt>Выход</dt><dd>{escape(outgoing)}</dd></div></dl><section class="task-contribution"><p class="eyebrow">МОЙ ВКЛАД</p><ol>{''.join('<li>' + escape(c) + '</li>' for c in item['contributions'])}</ol></section>'''
        heading, protocol = PROTOCOLS[pid]
        metrics = ''.join(f'<div><strong>{escape(value)}</strong><span>{escape(label)}</span></div>' for value, label in item['metrics'])
        experiment = f'''<div class="sheet-heading"><div><p class="eyebrow">ЛИСТ 03 / ЭКСПЕРИМЕНТЫ</p><h3>{escape(heading)}</h3></div></div><div class="sheet-metrics">{metrics}</div><ol class="protocol-list">{''.join('<li><span>' + f'{i+1:02}' + '</span><p>' + escape(text) + '</p></li>' for i,text in enumerate(protocol))}</ol><div class="sheet-conclusion"><span>Результат</span><p>{escape(item['result'])}</p></div>'''
    tabs, sheets = [], []
    contents = [('task', 'Задача', task), ('scheme', 'Схема', interactive_scheme(item)), ('experiments', 'Эксперименты', experiment), ('errors', 'Ошибки', error_sheet(item))]
    for i, (key, label, content) in enumerate(contents):
        tabs.append(f'<button type="button" role="tab" id="{pid}-tab-{key}" data-sheet="{key}" aria-selected="{str(i==0).lower()}" aria-controls="{pid}-sheet-{key}" tabindex="{0 if i==0 else -1}"><span>{i+1:02}</span>{label}</button>')
        sheets.append(f'<section class="folder-sheet" id="{pid}-sheet-{key}" data-sheet-panel="{key}" role="tabpanel" aria-labelledby="{pid}-tab-{key}" tabindex="0">{content}<div class="sheet-titleblock"><span>{escape(FOLDER_TITLES[pid])} / {escape(item["number"])}</span><span>{escape(label.upper())} / ЛИСТ {i+1:02} ИЗ 04</span></div></section>')
    return f'''<article class="project-folder" data-folder="{pid}"><header class="folder-cover"><div><p class="eyebrow">ДЕЛО {item['number']} / {escape(item['context'])}</p><h2>{escape(item['title'])}</h2><p class="folder-summary">{escape(contribution)}</p><div class="folder-cover-links">{links}</div></div><div class="folder-miniature scene-{item['art']} scene-running" aria-hidden="true">{art}</div></header><div class="folder-sheet-tabs" role="tablist" aria-label="Листы проекта">{''.join(tabs)}</div><div class="folder-sheets">{''.join(sheets)}</div><footer class="folder-stack"><span>ИНСТРУМЕНТЫ</span><p>{escape(item.get('stack', stack))}</p></footer></article>'''

